connections = {
    "filesystem": ServerConnection(session=fs_session, status="connected"),
    "github": ServerConnection(session=gh_session, status="connected"),
    "database": ServerConnection(session=None, status="down"),
}

async def aggregate_tools(connections):
    aggregated = []
    for server_name, conn in connections.items():
        if conn.status != "connected":
            continue
        server_tools = await conn.session.list_tools()
        for tool in server_tools.tools:
            aggregated.append({
                "name": f"{server_name}.{tool.name}",
                "description": tool.description,
                "inputSchema": tool.inputSchema,
                "_server": server_name,
                "_original_name": tool.name,
            })
    return aggregated

async def call_tool(name, arguments, connections):
    server_name, _, original_name = name.partition(".")
    conn = connections.get(server_name)
    if conn is None or conn.status != "connected":
        raise ToolCallError(f"server {server_name} is not available right now")
    return await conn.session.call_tool(original_name, arguments)

async def handle_turn(user_request, connections):
    tools = await aggregate_tools(connections)
    response = await llm.complete(user_request, tools=tools)
    for call in response.tool_calls:
        try:
            result = await call_tool(call.name, call.arguments, connections)
        except ToolCallError as e:
            result = {"error": str(e)}
        yield result

async def reconnect_loop(connections):
    while True:
        for name, conn in connections.items():
            if conn.status == "down":
                try:
                    conn.session = await connect(name)
                    conn.status = "connected"
                except ConnectionError:
                    pass
        await asyncio.sleep(5)
